-- Canonical Gen V natural learnsets pinned to PokéAPI source; no client-submitted skill metadata.
create table trainer_internal.encounter_moves(id integer primary key,identifier text not null,display_name text not null,move_type text not null,damage_class text not null,move_target text not null);
create table trainer_internal.encounter_learnset(species_id integer not null check(species_id between 1 and 649),move_id integer references trainer_internal.encounter_moves(id),learned_level integer not null check(learned_level between 0 and 100),primary key(species_id,move_id));
create table trainer_internal.encounter_skill_events(id bigint generated always as identity primary key,room_id uuid not null references trainer_internal.encounter_rooms(id) on delete cascade,owner_id uuid not null references trainer_internal.accounts(owner_id) on delete cascade,request_id uuid not null,expected_revision bigint not null,move_id integer not null references trainer_internal.encounter_moves(id),created_at timestamptz not null default clock_timestamp(),unique(room_id,owner_id,request_id));
create index encounter_skill_room_order on trainer_internal.encounter_skill_events(room_id,id desc);
create index encounter_skill_owner_cooldown on trainer_internal.encounter_skill_events(room_id,owner_id,created_at desc);
create index encounter_skill_owner_fk on trainer_internal.encounter_skill_events(owner_id);
create index encounter_learnset_move_fk on trainer_internal.encounter_learnset(move_id);
alter table trainer_internal.encounter_moves enable row level security;
alter table trainer_internal.encounter_learnset enable row level security;
alter table trainer_internal.encounter_skill_events enable row level security;
revoke all on trainer_internal.encounter_moves,trainer_internal.encounter_learnset,trainer_internal.encounter_skill_events from public,anon,authenticated,trainer_api;
