create function trainer_internal.encounter_legal_moves(species integer,pokemon_level integer) returns jsonb
language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(move_id order by learned_level,identifier),'[]'::jsonb) from (
  select l.move_id,l.learned_level,m.identifier from trainer_internal.encounter_learnset l
   join trainer_internal.encounter_moves m on m.id=l.move_id
  where l.species_id=species and l.learned_level<=pokemon_level
  order by l.learned_level desc,m.identifier desc limit 4
 ) selected
$$;

create or replace function trainer_internal.encounter_view(room uuid,player uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',r.id,'revision',r.revision,'closed',r.closed or r.expires_at<=clock_timestamp(),
  'serverTime',extract(epoch from clock_timestamp()),
  'members',coalesce((select jsonb_agg(jsonb_build_object('isSelf',m.owner_id=player,'alias',a.alias,
   'pokemon',case when m.selected_id is not null then (select choice-'id' from jsonb_array_elements(trainer_internal.encounter_choices(m.owner_id,m.selected_id)) choice
    where choice->>'id'=m.selected_id limit 1) else null end) order by m.slot)
   from trainer_internal.encounter_members m join trainer_internal.accounts a on a.owner_id=m.owner_id where m.room_id=r.id),'[]'::jsonb),
  'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'actorIsSelf',e.owner_id=player,'moveID',m.id,
   'moveName',m.display_name,'type',m.move_type,'damageClass',m.damage_class,'target',m.move_target,
   'startsAt',extract(epoch from e.created_at)+0.8) order by e.id)
   from (select * from trainer_internal.encounter_skill_events where room_id=r.id order by id desc limit 8) e
   join trainer_internal.encounter_moves m on m.id=e.move_id),'[]'::jsonb))
 from trainer_internal.encounter_rooms r where r.id=room
$$;

create function trainer_internal.encounter_skill_request(token_hash text,action text,command jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare identity jsonb; player uuid; room uuid; target trainer_internal.encounter_rooms;
 own trainer_internal.encounter_members; mon jsonb; legal jsonb; prior trainer_internal.encounter_skill_events;
 chosen integer; request_uuid uuid; expected bigint;
begin
 identity:=trainer_internal.bind_profile_session(token_hash);player:=(identity->>'id')::uuid;
 room:=(command->>'roomID')::uuid;
 select * into target from trainer_internal.encounter_rooms where id=room for update;
 if not found then raise insufficient_privilege; end if;
 select * into own from trainer_internal.encounter_members where room_id=room and owner_id=player;
 if not found then raise insufficient_privilege; end if;
 if action='attack' then
  request_uuid:=(command->>'requestID')::uuid;chosen:=(command->>'moveID')::integer;expected:=(command->>'expectedRevision')::bigint;
  select * into prior from trainer_internal.encounter_skill_events where room_id=room and owner_id=player and request_id=request_uuid;
  if found then
   if prior.move_id is distinct from chosen or prior.expected_revision is distinct from expected then return jsonb_build_object('error','request_reused');end if;
   return trainer_internal.encounter_view(room,player);
  end if;
 end if;
 if target.closed or target.expires_at<=clock_timestamp() then return jsonb_build_object('error','room_closed');end if;
 if own.selected_id is null then return jsonb_build_object('moveIDs','[]'::jsonb,'error',case when action='attack' then 'not_owned' else null end);end if;
 select choice into mon from jsonb_array_elements(trainer_internal.encounter_choices(player,own.selected_id)) choice where choice->>'id'=own.selected_id limit 1;
 if mon is null then return jsonb_build_object('error','not_owned');end if;
 legal:=trainer_internal.encounter_legal_moves((mon->>'speciesID')::integer,(mon->>'level')::integer);
 if action='moves' then return jsonb_build_object('moveIDs',legal);end if;
 if action<>'attack' then raise insufficient_privilege;end if;
 if expected is distinct from target.revision then return jsonb_build_object('error','stale_revision');end if;
 if request_uuid is null or chosen is null or not legal @> jsonb_build_array(chosen) then return jsonb_build_object('error','illegal_move');end if;
 if not exists(select 1 from trainer_internal.encounter_members m where m.room_id=room and m.owner_id<>player and m.selected_id is not null
  and exists(select 1 from jsonb_array_elements(trainer_internal.encounter_choices(m.owner_id,m.selected_id)) choice where choice->>'id'=m.selected_id)) then
  return jsonb_build_object('error','opponent_not_ready');end if;
 if exists(select 1 from trainer_internal.encounter_skill_events where room_id=room and owner_id=player and created_at>clock_timestamp()-interval '2.5 seconds') then return jsonb_build_object('error','cooldown');end if;
 delete from trainer_internal.encounter_skill_events where room_id=room and id in(
  select id from trainer_internal.encounter_skill_events where room_id=room order by id desc offset 31);
 insert into trainer_internal.encounter_skill_events(room_id,owner_id,request_id,expected_revision,move_id) values(room,player,request_uuid,expected,chosen);
 update trainer_internal.encounter_rooms set revision=revision+1 where id=room;
 return trainer_internal.encounter_view(room,player);
end $$;
